<template>
    <div class="mobile-login-page">
        <!-- 登录表单 -->
        <div class="mobile-login-container">
            <div class="mobile-center-container">
                <!-- Logo 区域 -->
                <div class="mobile-logo-large">
                    <mobile-l-img :src="appLogo" :w="logoSize.width" :h="logoSize.height" />
                    <span class="mobile-logo-text">{{ appName }}</span>
                </div>

                <!-- 登录表单 -->
                <form class="mobile-login-form" @submit="handleFormSubmit">
                    <!-- 邮箱输入 -->
                    <div class="mobile-form-item">
                        <label class="mobile-form-label">{{ t('email') }}</label>
                        <div class="mobile-input-container" :class="{ 'input-error': emailError }">
                            <input
                                type="email"
                                v-model="loginForm.email"
                                :placeholder="t('emailPlaceholder')"
                                class="mobile-form-input"
                                @blur="validateEmail"
                                required
                            />
                            <mobile-l-img 
                                class="mobile-clear-icon" 
                                v-if="loginForm.email" 
                                @click="clearEmail" 
                                src="/static/images/close_icon.png" 
                                w="20px" 
                                h="20px"
                            />
                        </div>
                        <div class="mobile-error-message" v-if="emailError">{{ emailError }}</div>
                    </div>

                    <!-- 密码输入 -->
                    <div class="mobile-form-item">
                        <label class="mobile-form-label">
                            <span>{{ t('password') }}</span>
                            <span class="mobile-forgot-password" @click="clickForgotPassword">{{ t('forgotPassword') }}</span>
                        </label>
                        <div class="mobile-input-container" :class="{ 'input-error': passwordError }">
                            <input
                                :type="passwordVisible ? 'text' : 'password'"
                                v-model="loginForm.password"
                                :placeholder="t('passwordPlaceholder')"
                                class="mobile-form-input"
                                @blur="validatePassword"
                                required
                            />
                            <div class="mobile-password-toggle" @click="togglePasswordVisibility">
                                <mobile-l-img
                                    v-if="!passwordVisible"
                                    src="/static/images/eye_icon1.png"
                                    w="20px"
                                    h="20px"
                                />
                                <mobile-l-img 
                                    v-else 
                                    src="/static/images/eye_icon2.png" 
                                    w="20px" 
                                    h="20px" 
                                />
                            </div>
                        </div>
                        <div class="mobile-error-message" v-if="passwordError">{{ passwordError }}</div>
                    </div>

                    <!-- 登录按钮 -->
                    <div class="mobile-form-item">
                      <mobile-l-button
                            :text="t('login')"
                            :loadingText="t('loggingIn')"
                            :loading="loading"
                            :disabled="loading"
                            @onClick="clickSubmitLogin"
                            type="submit"
                        />
                    </div>
                </form>

                <!-- 服务条款 -->
                <div class="mobile-terms-container">
                    {{ $t('byContinuingYouAgreeToOur') }}
                    <span @click="clickGoToTerms" class="mobile-terms-text">{{ $t('terms') }}</span>
                    <span class="mobile-and-text">&nbsp;&nbsp;{{ $t('and') }}&nbsp;&nbsp;</span>
                    <span @click="clickGoToPrivacyPolicy" class="mobile-terms-text">{{ $t('privacyPolicy') }}</span>
                </div>
            </div>
        </div>
    </div>
</template>

<script setup>
// 引入区域
import { ref, reactive, computed, onMounted } from 'vue';
import { useI18n } from 'vue-i18n';
import { useRouter } from 'vue-router';
import MobileLImg from '@/mobile/components/mobile-l-img.vue';
import MobileLButton from '@/mobile/components/mobile-l-button.vue';
import { ROUTER_PATHS } from '@/router/constants';
import { getRouterParams } from '@/router/navigation';
import { ApiUser } from '@/api/api-user';
import { routerToTerms, routerToPrivacyPolicy } from '@/router/navigation';

// 框架变量
const { t } = useI18n();
const router = useRouter();

// 常量
const appName = ref(process.env.VITE_APP_TITLE);
const appLogo = ref(process.env.VITE_APP_LOGO);

// 响应式变量
const loginForm = reactive({
    email: '',
    password: ''
});
const emailError = ref('');
const passwordError = ref('');
const passwordVisible = ref(false);
const loading = ref(false);

// 计算属性区域
const logoSize = computed(() => {
    return { width: '100px', height: '100px' };
});

// 点击事件区域
const clickForgotPassword = () => {
    router.push(ROUTER_PATHS.FORGOT_PASSWORD);
};

const clickGoToTerms = () => {
    routerToTerms();
};

const clickGoToPrivacyPolicy = () => {
    routerToPrivacyPolicy();
};

const clickSubmitLogin = async (e) => {
    e.preventDefault();
    
    const isEmailValid = validateEmail();
    const isPasswordValid = validatePassword();

    if (!isEmailValid || !isPasswordValid) {
        return;
    }

    try {
        loading.value = true;
        await ApiUser.login(loginForm.email, loginForm.password);

        const routeParams = getRouterParams();
        const redirectPath = routeParams.redirect || ROUTER_PATHS.HOME;
        router.push(redirectPath);
    } catch (error) {
        console.error('Login failed:', error);
    } finally {
        loading.value = false;
    }
};

// 自定义事件区域
const togglePasswordVisibility = () => {
    passwordVisible.value = !passwordVisible.value;
};

const clearEmail = () => {
    loginForm.email = '';
};

// 业务逻辑区域
const validateEmail = () => {
    if (!loginForm.email) {
        emailError.value = t('emailRequired');
        return false;
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(loginForm.email)) {
        emailError.value = t('validEmail');
        return false;
    }

    emailError.value = '';
    return true;
};

const validatePassword = () => {
    if (!loginForm.password) {
        passwordError.value = t('passwordRequired');
        return false;
    }

    if (loginForm.password.length < 6 || loginForm.password.length > 20) {
        passwordError.value = t('loginPasswordLength');
        return false;
    }

    passwordError.value = '';
    return true;
};

const handleFormSubmit = (e) => {
    e.preventDefault();
    clickSubmitLogin(e);
};

// 周期函数区域
onMounted(() => {
    console.log('Mobile login page mounted, version:', import.meta.env.VITE_BUILD_VERSION);
});
</script>

